metrics.workdir_dsl:
workspace "Bookshop" "A simple online bookshop" {

    !identifiers hierarchical

    model {
        customer = person "Customer" "A customer who browses the catalogue and buys books online"

        bookshop = softwareSystem "Bookshop" "An online bookshop where customers can browse books and place orders" {
            webStore = container "Web Store" "The web application where customers browse the catalogue and place orders" "Web application"
            orderProcessor = container "Order Processor" "Processes and fulfils customer orders" "Batch service"
        }

        customer -> bookshop.webStore "browses the catalogue and places orders through" "HTTPS"
        bookshop.webStore -> bookshop.orderProcessor "submits new orders to" "Internal API"
    }

    views {
        systemContext bookshop "BookshopContext" {
            include *
            autoLayout
            title "System Context for Bookshop"
        }
    }
}
